import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"89. Modern Style: Clean and Readable C","description":"The Little Book of C — 89. Modern Style: Clean and Readable C","frontmatter":{"title":"89. Modern Style: Clean and Readable C","date":"2026-07-04","categories":"[C 教程]","tags":"[C, Little Book of C, Portable and Modern C]","description":"The Little Book of C — 89. Modern Style: Clean and Readable C","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":"89","sidebarWeight":"89","lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/089-Modern Style Clean and Readable C","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/089-Modern Style Clean and Readable C"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/089-Modern Style Clean and Readable C.md","filePath":"posts/c教程/en-US/09-Portable and Modern C/089-Modern Style Clean and Readable C.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/09-Portable and Modern C/089-Modern Style Clean and Readable C.md"};function o(l,e,p,d,r,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/089-Modern Style Clean and Readable C)</p><p>C has been around for over 50 years, and yet it keeps evolving. Modern C (C11–C23) combines the power of low-level programming with safer syntax, cleaner idioms, and new features that make code easier to reason about.</p><p>This section will help you write modern, readable, and maintainable C, the kind of C that feels timeless.</p><h4 id="step-1-think-clarity-over-cleverness" tabindex="-1">Step 1. Think “Clarity Over Cleverness” <a class="header-anchor" href="#step-1-think-clarity-over-cleverness" aria-label="Permalink to &quot;Step 1. Think “Clarity Over Cleverness”&quot;">​</a></h4><p>The golden rule of modern C is:</p><p>Write for humans, not compilers.</p><p>Compilers can handle complexity, your teammates (and future you) can’t.</p><p>Bad:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (i = n; i--; ) a[i] = 0;</span></span></code></pre></div><p>Good:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 0; i &lt; n; i++)</span></span>
<span class="line"><span>    a[i] = 0;</span></span></code></pre></div><p>Readability and simplicity always win.</p><h4 id="step-2-prefer-explicit-initialization" tabindex="-1">Step 2. Prefer Explicit Initialization <a class="header-anchor" href="#step-2-prefer-explicit-initialization" aria-label="Permalink to &quot;Step 2. Prefer Explicit Initialization&quot;">​</a></h4><p>Always initialize your variables. Uninitialized memory is one of the biggest sources of bugs.</p><p>Bad:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);</span></span></code></pre></div><p>Good:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 0;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);</span></span></code></pre></div><p>Also initialize arrays and structs explicitly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int arr[10] = {0};</span></span>
<span class="line"><span>struct Point p = { .x = 10, .y = 20 };</span></span></code></pre></div><h4 id="step-3-use-const-generously" tabindex="-1">Step 3. Use const Generously <a class="header-anchor" href="#step-3-use-const-generously" aria-label="Permalink to &quot;Step 3. Use const Generously&quot;">​</a></h4><p><code>const</code> communicates intent, “this value shouldn’t change.”</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const double PI = 3.14159;</span></span>
<span class="line"><span>void print(const char* message);</span></span></code></pre></div><p>This helps the compiler optimize, prevents accidental modification, and improves clarity.</p><h4 id="step-4-prefer-modern-standard-headers" tabindex="-1">Step 4. Prefer Modern Standard Headers <a class="header-anchor" href="#step-4-prefer-modern-standard-headers" aria-label="Permalink to &quot;Step 4. Prefer Modern Standard Headers&quot;">​</a></h4><p>Use standard headers like<code>&lt;stdint.h&gt;</code>,<code>&lt;stdbool.h&gt;</code>, and<code>&lt;stddef.h&gt;</code> for clear, portable code.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>bool is_even(uint32_t n) {</span></span>
<span class="line"><span>    return (n % 2) == 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Avoid using old-style typedefs like<code>typedef unsigned long ulong;</code> unless it improves meaning.</p><h4 id="step-5-use-bool-instead-of-int-for-logic" tabindex="-1">Step 5. Use bool Instead of int for Logic <a class="header-anchor" href="#step-5-use-bool-instead-of-int-for-logic" aria-label="Permalink to &quot;Step 5. Use bool Instead of int for Logic&quot;">​</a></h4><p>In old C, people used<code>int</code> for true/false. Modern C gives you<code>_Bool</code> via<code>&lt;stdbool.h&gt;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>bool done = false;</span></span>
<span class="line"><span>if (!done) {</span></span>
<span class="line"><span>    done = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This improves clarity and makes your code self-documenting.</p><h4 id="step-6-write-small-focused-functions" tabindex="-1">Step 6. Write Small, Focused Functions <a class="header-anchor" href="#step-6-write-small-focused-functions" aria-label="Permalink to &quot;Step 6. Write Small, Focused Functions&quot;">​</a></h4><p>Keep functions short, ideally one purpose per function.</p><p>Bad:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void handle_all() { /* does 10 things */ }</span></span></code></pre></div><p>Good:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void read_input(void);</span></span>
<span class="line"><span>void process_data(void);</span></span>
<span class="line"><span>void write_output(void);</span></span></code></pre></div><p>This makes testing and debugging far easier.</p><h4 id="step-7-avoid-macros-for-everything" tabindex="-1">Step 7. Avoid Macros for Everything <a class="header-anchor" href="#step-7-avoid-macros-for-everything" aria-label="Permalink to &quot;Step 7. Avoid Macros for Everything&quot;">​</a></h4><p>In early C, macros were overused for constants and functions. Today, prefer inline functions and<code>const</code> instead.</p><p>Bad:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define SQUARE(x) ((x) * (x))</span></span></code></pre></div><p>Good:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static inline int square(int x) { return x * x; }</span></span></code></pre></div><p>Inline functions are type-safe and debug-friendly.</p><h4 id="step-8-use-scoped-variables-and-declarations" tabindex="-1">Step 8. Use Scoped Variables and Declarations <a class="header-anchor" href="#step-8-use-scoped-variables-and-declarations" aria-label="Permalink to &quot;Step 8. Use Scoped Variables and Declarations&quot;">​</a></h4><p>Since C99, you can declare variables close to where they’re used:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 0; i &lt; n; i++) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, i);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Avoid keeping variables alive longer than necessary, this reduces bugs and clarifies scope.</p><h4 id="step-9-embrace-c23-features" tabindex="-1">Step 9. Embrace C23 Features <a class="header-anchor" href="#step-9-embrace-c23-features" aria-label="Permalink to &quot;Step 9. Embrace C23 Features&quot;">​</a></h4><p>C23 modernizes syntax and makes C safer and more expressive.</p><p>Highlights:</p><ul><li><code>typeof</code>, reuse variable types automatically</li><li><code>nullptr</code>, replaces<code>NULL</code></li><li><code>[[nodiscard]]</code>, warn if function return is ignored</li><li><code>auto</code>, type inference for local variables</li><li>UTF-8 character support and string literals</li><li><code>alignof</code>/<code>alignas</code> for precise memory layout</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[[nodiscard]] int divide(int a, int b) {</span></span>
<span class="line"><span>    if (b == 0) return 0;</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-10-tiny-code-modern-c23-example" tabindex="-1">Step 10. Tiny Code: Modern C23 Example <a class="header-anchor" href="#step-10-tiny-code-modern-c23-example" aria-label="Permalink to &quot;Step 10. Tiny Code: Modern C23 Example&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>[[nodiscard]] static inline uint32_t add(uint32_t a, uint32_t b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const uint32_t x = 10, y = 20;</span></span>
<span class="line"><span>    uint32_t sum = add(x, y);</span></span>
<span class="line"><span>    bool valid = (sum &gt; 0);</span></span>
<span class="line"><span>    if (valid)</span></span>
<span class="line"><span>        printf(&quot;Sum = %u\\n&quot;, sum);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile with a modern compiler (GCC 13+ or Clang 17+):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c23 modern.c -o modern</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sum = 30</span></span></code></pre></div><p>This code uses<code>[[nodiscard]]</code>,<code>bool</code>, and<code>const</code>, small touches that improve both style and safety.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Readable C code lasts for decades. The best systems code, in kernels, compilers, and libraries, looks simple because it follows clear patterns:</p><ul><li>Small, pure functions.</li><li>Explicit types.</li><li>No surprises in memory handling.</li></ul><p>Modern C doesn’t mean rewriting everything. It means writing intentional C, clear, correct, and expressive.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Refactor one of your old programs to use<code>&lt;stdint.h&gt;</code> and<code>&lt;stdbool.h&gt;</code>.</li><li>Replace macros with inline functions.</li><li>Add<code>const</code> wherever possible.</li><li>Try compiling with<code>-std=c23</code> and explore new warnings.</li><li>Make your functions pure and side-effect free where possible.</li></ol><p>Next, you’ll conclude this journey with Practice: Portable Multithreaded Program (90), a hands-on project that combines everything from memory management to threading and portability.</p>`,71)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
